// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Katı cisimler ve uzay geometrisi: prizma, piramit, silindir, koni, küre, kesit ve açınım problemleri (orta).
const ozMathematics17Orta = <(String, String, List<String>, String)>[
  ('Farklı üç yüzünün alanları 12 cm², 15 cm² ve 20 cm² olan bir dikdörtgenler prizmasının hacmi kaç santimetreküptür?', '60 santimetreküp', ['30 santimetreküp', '120 santimetreküp', '47 santimetreküp'], 'ab = 12, bc = 15, ac = 20 ise taraf tarafa çarpıldığında (abc)² = 12 × 15 × 20 = 3600 olur; buradan hacim V = abc = 60 cm³ bulunur.'),
  ('Bir köşesinden çıkan üç ayrıtının uzunlukları toplamı 14 cm ve yüzey alanı 132 cm² olan bir dikdörtgenler prizmasının cisim köşegeni kaç santimetredir?', '8 santimetre', ['6√2 santimetre', '10 santimetre', '√68 santimetre'], 'a + b + c = 14 ve 2(ab + bc + ac) = 132\'dir. (a + b + c)² = a² + b² + c² + 2(ab + bc + ac) özdeşliğinden 196 = e² + 132 ve e² = 64, e = 8 cm bulunur.'),
  ('Bir ayrıtı 4 cm olan bir küpün bir köşesinden başlayıp komşu iki yüz üzerinden yürüyerek bu köşeye en uzak olan cisim köşegeni ucundaki köşeye giden karıncanın alacağı en kısa yol kaç santimetredir?', '4√5 santimetre', ['4√3 santimetre', '12 santimetre', '8√2 santimetre'], 'Komşu iki yüz aynı düzleme açıldığında kenarları 4 cm ve 8 cm olan bir dikdörtgen oluşur; en kısa yol hipotenüs uzunluğu olan √(4² + 8²) = √80 = 4√5 cm\'dir.'),
  ('Ayrıtları 3 cm, 4 cm ve 5 cm olan dikdörtgenler prizmasının bir köşesinden cisim köşegeni ucundaki karşı köşeye yüzey üzerinden gidecek bir karıncanın alabileceği en kısa yol kaç santimetredir?', '√74 santimetre', ['√80 santimetre', '√90 santimetre', '5√2 santimetre'], 'Üç olası açınımda hipotenüs kareleri (3+4)² + 5² = 74, (3+5)² + 4² = 80 ve (4+5)² + 3² = 90\'dır; en küçüğü √74 cm olur.'),
  ('Birim kareli kağıt üzerinde çizilen 6 eş karelik bir şeklin küp açınımı OLMAMASI için aşağıdaki durumlardan hangisinin şekil içinde yer alması yeterlidir?', 'Dört karenin birleşerek 2×2 boyutunda büyük bir kare oluşturması', ['Dört karenin yan yana tek bir doğrusal şerit oluşturması', 'Üç karenin doğrusal dizilip diğer üçünün basamak oluşturması', 'Hiçbir satırda ikiden fazla karenin yan yana bulunmaması'], '11 farklı geçerli küp açınımının hiçbirinde 2×2\'lik bir kare blok bulunmaz; 2×2 kare blok katlandığında iki yüz mutlaka üst üste çakışır.'),
  ('Taban ayrıtları 8 cm ve 10 cm, yüksekliği 12 cm olan dikdörtgenler prizması biçimindeki kapalı kap yüksekliğinin dörtte üçü kadar suyla doludur; bu kap 12 cm ve 10 cm ayrıtlı yüzeyi üzerine yatırılırsa su yüksekliği kaç santimetre olur?', '6 santimetre', ['9 santimetre', '7,5 santimetre', '8 santimetre'], 'Suyun hacmi V = 8 × 10 × (12 × 3/4) = 8 × 10 × 9 = 720 cm³\'tür. Yeni taban alanı 12 × 10 = 120 cm² olduğundan yeni yükseklik 720 / 120 = 6 cm olur.'),
  ('Bir ayrıtı 6 cm olan içi dolu tahta bir küpün bir köşesinden bir ayrıtı 2 cm olan küçük bir küp kesilip çıkarılırsa kalan cismin yüzey alanı kaç santimetrekare olur?', '216 santimetrekare', ['192 santimetrekare', '228 santimetrekare', '208 santimetrekare'], 'Köşeden küp çıkarıldığında 2×2\'lik 3 kare yüz eksilir ancak iç kısımda tam olarak aynı alana sahip 3 yeni kare yüz oluştuğundan toplam yüzey alanı 6 × 6² = 216 cm² olarak kalır.'),
  ('Bir ayrıtı 8 cm olan küpün üst yüzünün merkezinden tabana dik doğrultuda bir ayrıtı 2 cm olan kare dik prizma tabana kadar boydan boya oyulup çıkarılırsa kalan cismin yüzey alanı ilk küpe göre nasıl değişir?', '56 santimetrekare artar', ['64 santimetrekare artar', '72 santimetrekare artar', '48 santimetrekare artar'], 'Üst ve alt tabandan 2×2 = 4\'er cm² olmak üzere toplam 8 cm² eksilir; içeride 4 × (2 × 8) = 64 cm² yanal alan eklenir. Net artış 64 - 8 = 56 cm² olur.'),
  ('Tabanı eşkenar üçgen olan bir dik prizmanın taban ayrıtı 6 cm ve yüksekliği 8 cm\'dir. Tabanın bir A köşesinden başlayıp üç yan yüzü de birer kez dolanarak A köşesinin tam üstündeki A\' köşesine ulaşan karıncanın en kısa yolu kaç santimetredir?', '√388 santimetre', ['10√3 santimetre', '26 santimetre', '√324 santimetre'], 'Üç yan yüz düzleme açıldığında yatay kenarı 3 × 6 = 18 cm ve dikey kenarı 8 cm olan bir dikdörtgen elde edilir; köşegen √(18² + 8²) = √(324 + 64) = √388 cm\'dir.'),
  ('Kare dik prizmanın taban ayrıtı 5 cm ve yüksekliği 12 cm\'dir. Alt tabanın bir köşesinden başlayıp yan yüzler üzerinden tam iki tur dolanarak üst tabanda aynı yanal ayrıt üzerindeki köşeye giden en kısa telin uzunluğu kaç santimetredir?', '√1744 santimetre', ['√544 santimetre', '28 santimetre', '52 santimetre'], 'Bir turda yatay açınım taban çevresi olan 4 × 5 = 20 cm, iki turda 40 cm olur; dikey uzunluk 12 cm olduğundan en kısa yol √(40² + 12²) = √(1600 + 144) = √1744 cm\'dir.'),
  ('Üç farklı yüzünün köşegen uzunlukları √13 cm, √20 cm ve √29 cm olan dikdörtgenler prizmasının cisim köşegeni kaç santimetredir?', '√31 santimetre', ['√62 santimetre', '6 santimetre', '2√15 santimetre'], 'a² + b² = 13, b² + c² = 20 ve a² + c² = 29 denklemleri toplandığında 2(a² + b² + c²) = 62 ve a² + b² + c² = 31 bulunur; cisim köşegeni √31 cm\'dir.'),
  ('Yanal yüzleri eşkenar üçgen olan bir kare dik piramidin bir ayrıtı 6√2 cm ise piramidin cisim yüksekliği kaç santimetredir?', '6 santimetre', ['6√2 santimetre', '3√6 santimetre', '9 santimetre'], 'Kare tabanın bir kenarı 6√2 cm olduğundan taban köşegeni 6√2 × √2 = 12 cm, yarısı 6 cm\'dir. Yan ayrıt da 6√2 cm olduğundan yükseklik h = √((6√2)² - 6²) = √(72 - 36) = 6 cm olur.'),
  ('Bir düzgün dörtyüzlünün bir ayrıtının uzunluğu 6 cm olduğuna göre bu cismin yüksekliği kaç santimetredir?', '2√6 santimetre', ['3√3 santimetre', '2√3 santimetre', '3√2 santimetre'], 'Ayrıtı a olan düzgün dörtyüzlünün yüksekliği h = a√6 / 3 formülüyle bulunur; a = 6 için h = 6√6 / 3 = 2√6 cm\'dir.'),
  ('Taban ayrıtı 10 cm ve cisim yüksekliği 12 cm olan düzgün kare piramidin tüm yüzey alanı kaç santimetrekaredir?', '360 santimetrekare', ['340 santimetrekare', '260 santimetrekare', '400 santimetrekare'], 'Taban yarı kenarı 5 cm ve yükseklik 12 cm olduğundan yan yüz yüksekliği 5-12-13 üçgeninden 13 cm\'dir. Yanal alan 4 × (10 × 13 / 2) = 260 cm², taban alanı 100 cm², toplam 360 cm²\'dir.'),
  ('Bir küpün bir ayrıtı %20 oranında artırılırsa hacmi yüzde kaç oranında artar?', '%72,8 oranında artar', ['%60 oranında artar', '%44 oranında artar', '%80 oranında artar'], 'Ayrıt uzunluğu 1,2 katına çıktığında hacim (1,2)³ = 1,728 katına çıkar; dolayısıyla hacimdeki artış %72,8 olur.'),
  ('Karşılıklı yüzlerindeki sayıların toplamı 7 olan standart bir zarın düzlemsel açınımında, doğrusal ve bitişik dizili 4 karenin sırasıyla 1, 2, X ve Y sayılarıyla numaralandırıldığı biliniyorsa X + Y toplamı kaçtır?', '11', ['9', '7', '10'], 'Doğrusal bitişik 4 karede 1. ile 3. kare ve 2. ile 4. kare karşılıklı yüzlerdir. Bu durumda 1 + X = 7\'den X = 6 ve 2 + Y = 7\'den Y = 5 bulunur; X + Y = 11\'dir.'),
  ('Taban ayrıtı 6 cm, yüksekliği 9 cm olan kare dik prizma tamamen suyla doludur. Bu suyun tamamı taban ayrıtı 9 cm olan boş bir kare dik piramide boşaltıldığında piramit tam dolduğuna göre piramidin yüksekliği kaç santimetredir?', '12 santimetre', ['8 santimetre', '16 santimetre', '9 santimetre'], 'Prizmadaki su hacmi 6² × 9 = 324 cm³\'tür. Piramit hacmi (9² × h) / 3 = 27h = 324 eşitliğinden h = 12 cm bulunur.'),
  ('Bir düzgün kare piramit, yüksekliğinin tam ortasından tabana paralel bir düzlemle kesiliyor. Elde edilen kesik piramidin hacminin, kesilmeden önceki büyük piramidin hacmine oranı kaçtır?', '7/8', ['3/4', '5/8', '15/16'], 'Benzerlik oranı k = 1/2 olduğundan üstteki küçük piramidin hacminin tüm piramide oranı k³ = 1/8\'dir; alttaki kesik piramide 1 - 1/8 = 7/8 kalır.'),
  ('Alt taban ayrıtı 8 cm, üst taban ayrıtı 2 cm ve yan yüz yüksekliği 5 cm olan düzgün kesik kare piramidin cisim yüksekliği kaç santimetredir?', '4 santimetre', ['3 santimetre', '2√5 santimetre', '√21 santimetre'], 'Alt ve üst taban merkezlerinden yan kenarlara inen dikmelerin farkı (8 - 2) / 2 = 3 cm\'dir. Yan yüz yüksekliği 5 cm hipotenüs olduğundan cisim yüksekliği √(5² - 3²) = 4 cm olur.'),
  ('Alt taban ayrıtı 6 cm, üst taban ayrıtı 3 cm ve yüksekliği 4 cm olan kesik kare piramidin hacmi kaç santimetreküptür?', '84 santimetreküp', ['72 santimetreküp', '96 santimetreküp', '108 santimetreküp'], 'Kesik piramit hacmi V = (h/3)(S₁ + S₂ + √(S₁S₂)) formülünden (4/3)(36 + 9 + √(36×9)) = (4/3)(45 + 18) = (4/3) × 63 = 84 cm³ bulunur.'),
  ('Taban ayrıtı 4 cm ve yüksekliği 10 cm olan kare dik prizma şeklindeki kapalı bir kapta 6 cm yüksekliğinde su vardır. Kap yan yüzlerinden biri üzerine yatırılırsa suyun yüksekliği kaç santimetre olur?', '2,4 santimetre', ['3 santimetre', '2,5 santimetre', '3,2 santimetre'], 'Su hacmi 4 × 4 × 6 = 96 cm³\'tür. Yan yüz alanı 4 × 10 = 40 cm² olduğundan yeni yükseklik 96 / 40 = 2,4 cm olur.'),
  ('İç boyutları 6 cm, 8 cm ve 15 cm olan dikdörtgenler prizması biçimindeki bir kapta, 6×8\'lik taban üzerindeyken 10 cm yüksekliğinde su vardır. İçine bir ayrıtı 4 cm olan içi dolu demir bir küp tamamen batacak şekilde bırakılırsa yeni su yüksekliği kaç santimetre olur?', '34/3 santimetre', ['11 santimetre', '12 santimetre', '35/3 santimetre'], 'Demir küpün hacmi 4³ = 64 cm³\'tür. Taban alanı 6 × 8 = 48 cm² olduğundan su seviyesi 64 / 48 = 4/3 cm yükselir; yeni yükseklik 10 + 4/3 = 34/3 cm olur.'),
  ('Bir küpün altı yüzünün ağırlık merkezlerini köşe kabul eden düzgün sekizyüzlünün hacminin, bu küpün hacmine oranı kaçtır?', '1/6', ['1/3', '1/4', '1/8'], 'Ayrıtı 2 birim olan küpün hacmi 8\'dir; yüz merkezlerinin oluşturduğu düzgün sekizyüzlü taban alanı 2 ve yüksekliği 1 olan iki eş kare piramitten oluşur: hacmi 2 × (2 × 1 / 3) = 4/3\'tür; oran (4/3) / 8 = 1/6 olur.'),
  ('Taban dik kenarları 6 cm ve 8 cm olan dik üçgen dik prizmanın en büyük yan yüzünün köşegeni 26 cm olduğuna göre bu prizmanın hacmi kaç santimetreküptür?', '576 santimetreküp', ['480 santimetreküp', '624 santimetreküp', '1152 santimetreküp'], 'Taban hipotenüsü 6-8-10 üçgeninden 10 cm\'dir. En büyük yan yüzün tabanı 10 cm ve köşegeni 26 cm olduğundan 10-24-26 üçgeninden yükseklik 24 cm\'dir; hacim (6×8/2) × 24 = 576 cm³ olur.'),
  ('Taban ayrıtı 6 cm olan düzgün altıgen dik prizmanın yüksekliği 5 cm\'dir. Alt tabanın bir köşesi ile üst tabanın bu köşeye en uzak olan köşesi arasındaki cisim köşegeninin uzunluğu kaç santimetredir?', '13 santimetre', ['√133 santimetre', '15 santimetre', '√109 santimetre'], 'Düzgün altıgende birbirine en uzak iki köşe arasındaki en uzun köşegen bir kenarın 2 katı yani 12 cm\'dir. Yükseklik 5 cm olduğundan aranan uzaklık 5-12-13 dik üçgeninden 13 cm bulunur.'),
  ('Taban ayrıtı 4 cm olan düzgün altıgen dik prizmanın yüksekliği 3 cm ise alt tabandaki bir A köşesinden üst tabanda bir kenar atlayarak gelen C\' köşesine prizmanın içinden çizilen doğru parçasının uzunluğu kaç santimetredir?', '√57 santimetre', ['5√2 santimetre', '7 santimetre', '√41 santimetre'], 'Düzgün altıgende bir kenar 4 cm ise kısa köşegen (120° karşısı) 4√3 cm\'dir. Yükseklik 3 cm olduğundan aranan uzunluk √((4√3)² + 3²) = √(48 + 9) = √57 cm olur.'),
  ('Yanal ayrıtı 12 cm ve bir yan yüzündeki ikizkenar üçgenin tepe açısı 30° olan düzgün üçgen piramidin A taban köşesinden başlayıp üç yan yüzü dolanarak tekrar A köşesine dönen bir karıncanın alacağı en kısa yol kaç santimetredir?', '12√2 santimetre', ['12√3 santimetre', '18 santimetre', '24 santimetre'], 'Üç yan yüz düzleme açıldığında tepe açıları toplamı 3 × 30° = 90° olan ve ikizkenarları 12 cm olan bir ikizkenar dik üçgen oluşur; A ile A\' arasındaki en kısa yol 12√2 cm\'dir.'),
  ('Bir yan yüzünün tepe açısı 20° ve yan ayrıt uzunluğu 10 cm olan düzgün altıgen piramidin bir taban köşesinden başlayıp tüm yan yüzleri birer kez geçerek başladığı köşeye dönen karıncanın en kısa yolu kaç santimetredir?', '10√3 santimetre', ['10√2 santimetre', '20 santimetre', '15 santimetre'], 'Altı eş yan yüz düzleme açıldığında tepe açısı 6 × 20° = 120° ve yan kenarları 10 cm olan bir ikizkenar üçgen elde edilir; 30°-30°-120° üçgeninden en kısa yol 10√3 cm olur.'),
  ('Taban ayrıtları 4 cm ve 9 cm, yüksekliği 12 cm olan dikdörtgenler prizması ile aynı hacme ve aynı yüksekliğe sahip bir kare dik prizmanın yüzey alanı, dikdörtgenler prizmasının yüzey alanından kaç santimetrekare daha azdır?', '24 santimetrekare', ['12 santimetrekare', '36 santimetrekare', '48 santimetrekare'], 'Dikdörtgenler prizmasının hacmi 4×9×12 = 432 cm³, alanı 2(36 + 48 + 108) = 384 cm²\'dir. Kare prizmanın taban alanı 36 cm² (kenarı 6 cm) olur; alanı 2(36) + 4×6×12 = 360 cm²\'dir; fark 384 - 360 = 24 cm²\'dir.'),
  ('Bir dik prizmanın taban çokgeninin kenar sayısı 3 artırıldığında prizmanın ayrıt sayısı, yüz sayısı ve köşe sayısının toplamı kaç artar?', '18 artar', ['9 artar', '12 artar', '15 artar'], 'n kenarlı prizmada ayrıt (3n), yüz (n+2) ve köşe (2n) toplamı 6n + 2\'dir. n sayısı 3 artırıldığında toplam 6(n+3) + 2 - (6n + 2) = 18 artar.'),
  ('Tabanı ikizkenar yamuk olan bir dik prizmanın tabanının paralel kenarları 4 cm ve 10 cm, paralel olmayan eş kenarları 5 cm ve prizmanın yüksekliği 7 cm ise prizmanın hacmi kaç santimetreküptür?', '196 santimetreküp', ['140 santimetreküp', '210 santimetreküp', '168 santimetreküp'], 'İkizkenar yamukta yükseklik indirildiğinde tabanda (10-4)/2 = 3 cm kalır; 3-4-5 üçgeninden yamuğun yüksekliği 4 cm, alanı ((4+10)/2)×4 = 28 cm² olur; hacim 28 × 7 = 196 cm³\'tür.'),
  ('Boyutları 12 cm, 18 cm ve 30 cm olan dikdörtgenler prizması biçimindeki büyük bir peynir kalıbı, hiç parça artmayacak şekilde birbirine eş en büyük hacimli küp dilimlere ayrılırsa kaç adet küp elde edilir?', '30 adet küp', ['15 adet küp', '60 adet küp', '45 adet küp'], 'EBOB(12, 18, 30) = 6 cm küpün bir ayrıtıdır. Küp sayısı (12/6) × (18/6) × (30/6) = 2 × 3 × 5 = 30 adet olarak bulunur.'),
  ('Boyutları 2 cm, 3 cm ve 4 cm olan dikdörtgenler prizması şeklindeki tuğlalar kullanılarak içi dolu en küçük hacimli bir küp yapılmak istendiğinde kaç adet tuğla gerekir?', '72 adet tuğla', ['36 adet tuğla', '24 adet tuğla', '144 adet tuğla'], 'EKOK(2, 3, 4) = 12 cm oluşturulacak küpün bir ayrıtıdır. Gereken tuğla sayısı (12/2) × (12/3) × (12/4) = 6 × 4 × 3 = 72 adettir.'),
  ('Üstü açık ve taban ayrıtı 6 cm, yüksekliği 8 cm olan tamamen su dolu kare dik prizma biçimindeki bir kap, tabanının bir ayrıtı yerde kalacak biçimde yatay düzlemle 45° açı yapacak şekilde eğilirse kaptan kaç santimetreküp su dökülür?', '108 santimetreküp', ['144 santimetreküp', '72 santimetreküp', '96 santimetreküp'], 'Kap 45° eğildiğinde üst kısımda dökülen su bölgesi, dik kenarları 6 cm ve 6 cm, derinliği 6 cm olan bir dik üçgen dik prizma oluşturur; dökülen hacim (6 × 6 / 2) × 6 = 108 cm³\'tür.'),
  ('Ayrıt uzunlukları 1, 2 ve 3 sayılarıyla doğru orantılı olan bir dikdörtgenler prizmasının cisim köşegeni 2√14 cm olduğuna göre yüzey alanı kaç santimetrekaredir?', '88 santimetrekare', ['44 santimetrekare', '96 santimetrekare', '64 santimetrekare'], 'Ayrıtlar k, 2k ve 3k ise k² + 4k² + 9k² = 14k² = (2√14)² = 56 olur; buradan k² = 4 ve k = 2 bulunur. Ayrıtlar 2, 4, 6 cm olup yüzey alanı 2(8 + 24 + 12) = 88 cm²\'dir.'),
  ('Taban ayrıtları 6 cm ve 10 cm, yüksekliği 8 cm olan dikdörtgenler prizmasının alt taban köşesi A\'dan başlayıp yan yüzler üzerinden tam bir tur atarak A\'nın üstündeki E köşesine giden karıncanın alacağı en kısa yol kaç santimetredir?', '8√17 santimetre', ['32 santimetre', '40 santimetre', '16√5 santimetre'], 'Dört yan yüz düzleme açıldığında yatay uzunluk taban çevresi olan 2(6 + 10) = 32 cm, dikey uzunluk ise yükseklik olan 8 cm\'dir. Hipotenüs √(32² + 8²) = 8√(16 + 1) = 8√17 cm bulunur.'),
  ('Taban ayrıtı 8 cm, yüksekliği 7 cm olan kare dik prizmanın alt taban köşesi A\'dan çıkıp önce ABFE yan yüzü, sonra EFGH üst yüzü üzerinden yürüyerek üst yüzün ağırlık merkezi O\'ya giden karıncanın en kısa yolu kaç santimetredir?', '√137 santimetre', ['13 santimetre', '√145 santimetre', '15 santimetre'], 'ABFE yan yüzü ile EFGH üst yüzü aynı düzleme açıldığında O noktasının EF kenarına dik uzaklığı 4 cm, E kenarına yatay uzaklığı 4 cm\'dir. A\'dan O\'ya yatay mesafe 4 cm, dikey mesafe 7 + 4 = 11 cm olduğundan en kısa yol √(4² + 11²) = √137 cm olur.'),
  ('Düzgün altıgen dik prizmanın yanal alanı 144 cm² ve yüksekliği 6 cm olduğuna göre bu prizmanın bir tabanının alanı kaç santimetrekaredir?', '24√3 santimetrekare', ['16√3 santimetrekare', '36√3 santimetrekare', '12√3 santimetrekare'], 'Yanal alan 6a × 6 = 36a = 144 olduğundan altıgenin bir kenarı a = 4 cm\'dir. Düzgün altıgenin alanı 6 × (4²√3 / 4) = 24√3 cm² olur.'),
  ('Bir kare dik piramidin yan ayrıt uzunluğu 10 cm ve taban köşegeni 12 cm ise bu piramidin hacmi kaç santimetreküptür?', '192 santimetreküp', ['288 santimetreküp', '144 santimetreküp', '96√2 santimetreküp'], 'Taban köşegeni e = 12 cm ise kare tabanın alanı e² / 2 = 144 / 2 = 72 cm² ve yarı köşegen 6 cm\'dir. Yükseklik 6-8-10 üçgeninden h = 8 cm olup hacim (72 × 8) / 3 = 192 cm³ bulunur.'),
  ('Taban ayrıtı 6 cm olan düzgün altıgen piramidin cisim yüksekliği 4 cm olduğuna göre yan ayrıtlarından birinin uzunluğu kaç santimetredir?', '2√13 santimetre', ['5 santimetre', '2√10 santimetre', '8 santimetre'], 'Düzgün altıgende merkezden köşeye uzaklık taban ayrıtına eşit yani 6 cm\'dir. Cisim yüksekliği 4 cm ile bu yarıçap dik üçgen oluşturur: yan ayrıt √(6² + 4²) = √52 = 2√13 cm\'dir.'),
  ('Düzgün dörtyüzlünün tüm ayrıtlarının uzunlukları toplamı 24√2 cm ise tüm yüzey alanı kaç santimetrekaredir?', '32√3 santimetrekare', ['16√3 santimetrekare', '24√3 santimetrekare', '48√3 santimetrekare'], 'Düzgün dörtyüzlünün 6 eş ayrıtı vardır: 6a = 24√2 ise a = 4√2 cm\'dir. Toplam yüzey alanı 4 eşkenar üçgenin alanı olan a²√3 = (4√2)²√3 = 32√3 cm² bulunur.'),
  ('Bir piramit tabana paralel iki farklı düzlemle yüksekliği üç eşit parçaya bölünecek şekilde kesiliyor. Ortadaki kesik piramidin hacminin en alttaki kesik piramidin hacmine oranı kaçtır?', '7/19', ['8/27', '7/26', '1/3'], 'Benzerlik oranları 1 : 2 : 3 olduğundan üstten itibaren toplam piramit hacimleri V, 8V ve 27V olur; dilimlerin hacimleri sırasıyla V, 7V ve 19V olduğundan orta dilimin alt dilime oranı 7/19\'dur.'),
  ('İç boyutları 10 cm, 12 cm ve 20 cm olan dikdörtgenler prizması biçimindeki kapta 10×12 tabanı üzerindeyken 8 cm yüksekliğinde su vardır. Kaba hacmi 360 cm³ olan ve suda batıp çözünmeyen bir taş atılırsa su seviyesi kaç santimetre yükselir?', '3 santimetre yükselir', ['11 santimetre yükselir', '2,5 santimetre yükselir', '4 santimetre yükselir'], 'Yükselen su hacmi taşın hacmine eşittir. Taban alanı 10 × 12 = 120 cm² olduğundan yükselme miktarı Δh = 360 / 120 = 3 cm\'dir (toplam seviye 11 cm < 20 cm olduğundan taşma olmaz).'),
  ('Birim küplerden oluşturulmuş 3×3×3 boyutundaki büyük küpün dış yüzeyi tamamen sarıya boyanıp birim küpler birbirinden ayrılıyor. Yalnızca tek bir yüzü sarı boyalı olan kaç adet birim küp vardır?', '6 adet birim küp', ['12 adet birim küp', '8 adet birim küp', '1 adet birim küp'], 'Tek yüzü boyalı olan birim küpler her bir yüzün tam ortasında yer alan küplerdir; 3×3\'lük 6 yüzün her birinin merkezinde (3-2)² = 1 küp bulunduğundan toplam 6 × 1 = 6 adettir.'),
  ('Karşılıklı yüzlerinde A-F, B-D ve C-E harfleri bulunan bir küpün düzlemsel açınımında ortada B karesi, B\'nin solunda A, üstünde C, sağında F karesi varsa D karesinin B\'ye göre konumu aşağıdakilerden hangisi OLABİLİR?', 'F karesinin hemen sağında', ['B karesinin hemen altında', 'A karesinin hemen üstünde', 'C karesinin hemen solunda'], 'B ile D karşılıklı yüzler olduğundan aralarında aynı doğrultuda bir kare boşluk bulunmalıdır; F karesi B\'nin sağında olduğundan F\'nin hemen sağındaki kare katlandığında B\'nin tam karşısına gelir.'),
  ('Dik kenarları 9 cm ve 12 cm olan dik üçgen dik prizma biçimindeki kapalı kap, dik üçgen tabanı üzerindeyken 6 cm yüksekliğinde su içermektedir. Prizmanın yüksekliği 10 cm olduğuna göre kap hipotenüse ait en büyük yan yüzü üzerine yatırılırsa su yüksekliği kaç santimetre olur?', '2,16 santimetre', ['3,24 santimetre', '2,4 santimetre', '3,6 santimetre'], 'Taban alanı (9 × 12) / 2 = 54 cm² olduğundan su hacmi 54 × 6 = 324 cm³\'tür. Hipotenüs 9-12-15 üçgeninden 15 cm olup en büyük yan yüzün alanı 15 × 10 = 150 cm²\'dir; yeni su yüksekliği 324 / 150 = 2,16 cm olur.'),
  ('Bir dikdörtgenler prizmasının ayrıtları a, b ve c\'dir. 1/a + 1/b + 1/c = 3/4 ve prizmanın yüzey alanı 96 cm² olduğuna göre prizmanın hacmi kaç santimetreküptür?', '64 santimetreküp', ['48 santimetreküp', '72 santimetreküp', '32 santimetreküp'], 'Payda eşitlendiğinde (bc + ac + ab) / (abc) = 3/4 olur. Yüzey alanı 2(ab + bc + ac) = 96 olduğundan ab + bc + ac = 48 cm²\'dir; 48 / V = 3/4 eşitliğinden V = 64 cm³ bulunur.'),
  ('Ayrıtları 5 cm, 6 cm ve 7 cm olan dikdörtgenler prizmasının tüm ayrıtlarından 1 cm uzaklıkta değil; her ayrıtı 2 katına çıkarılırsa yüzey alanı ve hacmi sırasıyla kaç katına çıkar?', 'Yüzey alanı 4 katına, hacmi 8 katına', ['Yüzey alanı 2 katına, hacmi 4 katına', 'Yüzey alanı 4 katına, hacmi 6 katına', 'Yüzey alanı 6 katına, hacmi 8 katına'], 'Benzer katı cisimlerde uzunluklar k = 2 katına çıkarıldığında alanlar k² = 4 katına, hacimler ise k³ = 8 katına çıkar.'),
  ('Taban ayrıtları 8 cm ve 15 cm olan dikdörtgenler prizmasının köşegen düzlemi (karşılıklı iki paralel yanal ayrıtı birleştiren dikdörtgensel kesit) 170 cm² alana sahip olduğuna göre prizmanın hacmi kaç santimetreküptür?', '1200 santimetreküp', ['600 santimetreküp', '2040 santimetreküp', '1360 santimetreküp'], 'Taban köşegeni 8-15-17 üçgeninden 17 cm\'dir. Köşegen düzleminin alanı 17 × h = 170 olduğundan h = 10 cm bulunur; hacim 8 × 15 × 10 = 1200 cm³\'tür.'),
  ('Kare dik piramidin taban ayrıtı 8 cm ve yan ayrıtları 4√6 cm\'dir. Karşılıklı iki yan ayrıtı ve bir taban köşegenini içeren üçgensel kesitin alanı kaç santimetrekaredir?', '32√2 santimetrekare', ['32√3 santimetrekare', '64 santimetrekare', '16√6 santimetrekare'], 'Kesit üçgeninin tabanı karenin köşegeni olan 8√2 cm\'dir. Yan ayrıt 4√6 cm ve yarı köşegen 4√2 cm olduğundan cisim yüksekliği h = √((4√6)² - (4√2)²) = √(96 - 32) = 8 cm\'dir; kesit alanı (8√2 × 8) / 2 = 32√2 cm² olur.'),
  ('Üstü açık küp şeklindeki bir su deposunun iç ayrıtı 12 dm\'dir ve depo tamamen suyla doludur. Depo tabanının bir ayrıtı etrafında 30° eğildiğinde depodan kaç litre su dökülür?', '288√3 litre', ['144√3 litre', '432 litre', '216√3 litre'], 'Depo 30° eğildiğinde dökülen su dik kenarları 12 dm ve 12×tan30° = 4√3 dm, derinliği 12 dm olan bir dik üçgen dik prizmadır; hacmi ((12 × 4√3) / 2) × 12 = 288√3 dm³ yani 288√3 litredir.'),
  ('Bir dikdörtgenler prizmasının köşelerinden birinin koordinatları orijin (0, 0, 0) ve cisim köşegeni ucundaki karşı köşenin koordinatları (3, 6, 6) olup yüzeyleri koordinat düzlemleriyle çakışıktır. Orijinden karşı köşeye yüzey üzerinden giden karıncanın en kısa yolu kaç birimdir?', '3√13 birim', ['9 birim', '3√17 birim', '15 birim'], 'Ayrıtlar 3, 6 ve 6 birimdir. En kısa yüzey yolu için en küçük iki ayrıt toplanır: √((3 + 6)² + 6²) = √(81 + 36) = √117 = 3√13 birimdir.'),
  ('Taban yarıçapı yerine çevrel çember yarıçapı 8 cm olan düzgün sekizgen dik prizmanın yüksekliği 5√2 cm olduğuna göre bu prizmanın hacmi kaç santimetreküptür?', '1280 santimetreküp', ['640√2 santimetreküp', '960 santimetreküp', '1024 santimetreküp'], 'Düzgün sekizgen merkez açısı 45° olan 8 eş ikizkenar üçgenden oluşur: Taban alanı 8 × ((1/2) × 8 × 8 × sin45°) = 256 × (√2 / 2) = 128√2 cm²\'dir; hacim 128√2 × 5√2 = 1280 cm³ olur.'),
  ('Alt taban çevresi 36 cm, üst taban çevresi 20 cm ve yan yüz yüksekliği 7 cm olan düzgün kesik kare piramidin yanal alanı kaç santimetrekaredir?', '196 santimetrekare', ['180 santimetrekare', '392 santimetrekare', '168 santimetrekare'], 'Düzgün kesik piramidin yanal alanı ((Alt Çevre + Üst Çevre) / 2) × Yan Yüz Yüksekliği formülünden ((36 + 20) / 2) × 7 = 28 × 7 = 196 cm² bulunur.'),
  ('Taban dik kenarları 5 cm ve 12 cm olan dik üçgen dik prizmanın içine sığabilecek ve tabanları prizmanın taban düzlemleri üzerinde olan en büyük dik dairesel silindirin çapı kaç santimetredir (prizmanın iç teğet dairesi ilişkisiyle prizmanın yan yüzlerine teğet noktalara uzaklığı toplamı sorulsaydı: iç teğet çemberin merkezi prizma eksenidir; bu eksenin üç yan yüze olan dik uzaklıkları toplamı kaç santimetredir)?', '6 santimetre', ['4 santimetre', '7,5 santimetre', '9 santimetre'], '5-12-13 dik üçgeninde iç teğet çember yarıçapı r = (5 + 12 - 13) / 2 = 2 cm\'dir. Bu eksen noktasının her bir yan yüze dik uzaklığı 2 cm olduğundan üç yan yüze dik uzaklıkları toplamı 3 × 2 = 6 cm\'dir.'),
  ('Bir küpün 8 köşesinden rastgele seçilen 3 köşenin bir dik üçgenin köşeleri olma özelliğini sağlamadığı tek durum, seçilen üçgenin eşkenar üçgen olmasıdır. Bir ayrıtı 2 cm olan küpte köşeleri küpün köşeleri olan bir eşkenar üçgenin çevresi kaç santimetredir?', '6√2 santimetre', ['6 santimetre', '6√3 santimetre', '4√2 + 2√3 santimetre'], 'Küpün köşelerini birleştiren doğru parçaları sadece 2 cm (ayrıt), 2√2 cm (yüzey köşegeni) veya 2√3 cm (cisim köşegeni) olabilir; üç kenarı eşit üçgen yalnızca üç yüzey köşegeninin birleşmesiyle oluşur ve çevresi 3 × 2√2 = 6√2 cm\'dir.'),
  ('Yüksekliği 9 cm olan düzgün kare piramit, tabandan 3 cm yükseklikten tabana paralel bir düzlemle kesilerek üstteki piramit atılıyor. Kalan kesik piramidin üst taban alanı 16 cm² olduğuna göre kesik piramidin alt taban alanı kaç santimetrekaredir?', '36 santimetrekare', ['64 santimetrekare', '24 santimetrekare', '48 santimetrekare'], 'Üstteki atılan piramidin yüksekliği 9 - 3 = 6 cm, tüm piramidin yüksekliği 9 cm\'dir. Benzerlik oranı k = 6/9 = 2/3 olduğundan alanlar oranı k² = 4/9\'dur; 16 / S_alt = 4/9 eşitliğinden S_alt = 36 cm² bulunur.'),
  ('Yarıçapı 15 cm olan bir küre, merkezinden 9 cm uzaklıktaki bir düzlemle kesiliyor. Oluşan kesit dairesinin çevresi kaç π santimetredir?', '24', ['12', '18', '36'], 'Kesit yarıçapı k için 9² + k² = 15² bağıntısından k = 12 cm bulunur; kesit çemberinin çevresi 2πk = 24π santimetredir.'),
  ('Merkezinden 8 birim uzaklıktaki bir düzlemle kesildiğinde kesit alanı 36π birimkare olan kürenin yüzey alanı kaç π birimkaredir?', '400', ['200', '100', '576'], 'Kesit alanı πk² = 36π ise k = 6 birimdir; küre yarıçapı r² = 8² + 6² = 100 olur ve küre yüzey alanı 4πr² = 400π birimkare bulunur.'),
  ('Bir kürenin merkezinin aynı tarafında bulunan paralel iki düzlem küreyi kesmektedir. Kesit dairelerinin yarıçapları 5 cm ve 12 cm, kürenin yarıçapı 13 cm olduğuna göre iki düzlem arasındaki uzaklık kaç cm\'dir?', '7', ['17', '11', '13'], 'Merkezin 5 cm yarıçaplı kesite uzaklığı √(13² - 5²) = 12 cm, 12 cm yarıçaplı kesite uzaklığı √(13² - 12²) = 5 cm\'dir; aynı tarafta olduklarından aralarındaki fark 12 - 5 = 7 cm olur.'),
  ('Yarıçapı 17 birim olan bir kürenin merkezinin zıt taraflarında yer alan paralel iki kesit dairesinin yarıçapları 8 birim ve 15 birimdir. Bu iki kesit düzlemi arasındaki dik uzaklık kaç birimdir?', '23', ['17', '19', '25'], 'Merkezden uzaklıklar Pisagor ile √(17² - 8²) = 15 birim ve √(17² - 15²) = 8 birimdir; kesitler merkezin zıt taraflarında olduğundan aradaki uzaklık 15 + 8 = 23 birimdir.'),
  ('Kürenin merkezinden geçen en büyük kesitin alanı 64π cm² olduğuna göre, merkezden 2√7 cm uzaklıktaki düzlemsel kesitin alanı kaç π cm² olur?', '36', ['28', '48', '54'], 'πr² = 64π ise r² = 64\'tür; aranan kesitin yarıçapı k için k² = r² - (2√7)² = 64 - 28 = 36 bulunur ve kesit alanı πk² = 36π cm² olur.'),
  ('Yüzey alanı 192π birimkare olan bir kürenin içine yerleştirilebilecek en büyük hacimli küpün bir ayrıtı kaç birimdir?', '8', ['12', '4√3', '8√3'], '4πr² = 192π ise r² = 48 ve r = 4√3 birimdir; çap 8√3 küpün cisim köşegeni (a√3) olduğundan küpün bir ayrıtı a = 8 birim bulunur.'),
  ('Hacmi 216 cm³ olan bir küpün tüm yüzlerine içten teğet olan küre ile küp arasında kalan boşluğun hacmi kaç cm³\'tür?', '216 - 36π', ['216 - 72π', '216 - 108π', '216 - 48π'], 'Küpün ayrıtı ∛216 = 6 cm\'dir; iç teğet kürenin yarıçapı r = 3 cm ve hacmi (4/3)π · 3³ = 36π cm³ olduğundan aradaki boşluk 216 - 36π cm³ olur.'),
  ('Bir küpün tüm köşelerinden geçen çevrel kürenin hacmi, aynı küpün yüzlerine içten teğet olan kürenin hacminin kaç katıdır?', '3√3', ['9√3', '6√3', '12'], 'Çevrel küre yarıçapının iç teğet küre yarıçapına oranı √3 olduğu için hacimler oranı (√3)³ = 3√3 katıdır.'),
  ('Yarıçapı 5 birim olan bir kürenin içine, yüksekliği 8 birim olan en büyük hacimli dik dairesel silindir yerleştiriliyor. Bu silindirin hacmi kaç π birimküptür?', '72', ['144', '96', '108'], 'Küre merkezinden silindir tabanına uzaklık 8/2 = 4 birimdir; silindir taban yarıçapı R = √(5² - 4²) = 3 birim ve hacmi π · 3² · 8 = 72π birimküp olur.'),
  ('Taban yarıçapı 4 cm ve yüksekliği 6 cm olan dik dairesel silindirin alt ve üst taban çemberleri küre yüzeyine değecek biçimde bu silindiri çevreleyen kürenin yüzey alanı kaç π cm²\'dir?', '100', ['144', '196', '120'], 'Silindir eksen kesiti 8 cm\'ye 6 cm bir dikdörtgendir; köşegeni küre çapına eşittir: 2r = √(8² + 6²) = 10 cm, r = 5 cm ve alan 4π · 5² = 100π cm² olur.'),
  ('Arşimet\'in klasik teoremine göre, taban yarıçapı r ve yüksekliği 2r olan bir dik silindirin içine teğet yerleştirilen kürenin hacminin silindirin hacmine oranı kaçtır?', '2/3', ['1/2', '3/4', '4/9'], 'Kürenin hacmi (4/3)πr³, silindirin hacmi ise πr² · (2r) = 2πr³ olduğundan oran [(4/3)πr³] / [2πr³] = 2/3 bulunur.'),
  ('Taban yarıçapı r ve yüksekliği 2r olan dik dairesel silindirin sadece yan yüzey alanı ile içine tam teğet yerleştirilen kürenin tüm yüzey alanı karşılaştırıldığında hangisi doğrudur?', 'Birbirine tam olarak eşittir', ['Kürenin alanı silindirin yan alanının üçte ikisidir', 'Silindirin yan alanı kürenin alanından %50 fazladır', 'Kürenin alanı silindirin yan alanının yarısı kadardır'], 'Silindirin yan alanı 2πr · h = 2πr · (2r) = 4πr² olup yarıçapı r olan kürenin tüm yüzey alanı olan 4πr² değerine tam eşittir.'),
  ('Yarıçapı 10 cm olan bir kürenin içine tepe noktası ve taban çemberi küre yüzeyinde kalacak şekilde yüksekliği 18 cm olan bir dik koni yerleştiriliyor. Koninin hacmi kaç π cm³\'tür?', '216', ['432', '324', '288'], 'Küre merkezi ile koni tabanı arası uzaklık 18 - 10 = 8 cm\'dir; koni taban yarıçapı R = √(10² - 8²) = 6 cm ve koni hacmi (1/3)π · 6² · 18 = 216π cm³ bulunur.'),
  ('Taban yarıçapı 5 birim ve ana doğrusu 13 birim olan bir dik dairesel koninin içine yerleştirilen iç teğet kürenin yüzey alanı kaç π birimkaredir?', '400/9', ['100/3', '200/9', '160/3'], 'Yükseklik √(13² - 5²) = 12 birimdir; eksen kesiti kenarları 13, 13, 10 olan üçgendir (alan = 60, u = 18). Küre yarıçapı r = 60/18 = 10/3 birim ve yüzey alanı 4π(10/3)² = 400π/9 birimkaredir.'),
  ('İç yarıçapı 4 cm, dış yarıçapı 5 cm olan içi boş küresel bir metal kabuğun dökümünde kullanılan metalin hacmi kaç π cm³\'tür?', '244/3', ['124/3', '184/3', '216/3'], 'Kabuk hacmi dış küre ile iç boşluğun hacim farkıdır: (4/3)π(5³ - 4³) = (4/3)π(125 - 64) = 244π/3 cm³ bulunur.'),
  ('Taban yarıçapı 6 cm olan dik dairesel silindir biçimindeki kapta yeterince su vardır. Suya yarıçapı 3 cm olan demir bir küre atılıp tamamen battığında su seviyesi kaç cm yükselir?', '1', ['1,5', '2,5', '3'], 'Batan kürenin hacmi yükselen silindirik su hacmine eşittir: (4/3)π · 3³ = π · 6² · h eşitliğinden 36π = 36πh ve h = 1 cm bulunur.'),
  ('Merkezleri arasındaki uzaklık 12 birim olan eş iki küre dıştan birbirine teğettir. Bu iki küreyi içine alabilecek en küçük dikdörtgenler prizmasının hacmi kaç birimküptür?', '3456', ['1728', '2304', '4096'], 'Eş küreler dıştan teğet ve merkezler arası 12 birim ise her birinin yarıçapı 6 birim, çapı 12 birimdir; prizmanın ayrıtları 12, 12 ve 24 birim olacağından hacmi 12 · 12 · 24 = 3456 birimküptür.'),
  ('Merkez açısı 60° olan bir küre diliminin tüm yüzey alanı (iki yarım daire yan yüzeyi dahil), yarıçap r cinsinden kaç πr² olur?', '5/3', ['2/3', '4/3', '7/3'], 'Dilimin küresel kabuk alanı (60/360) · 4πr² = (2/3)πr²\'dir; yanlardaki iki yarım daire kesiti bir tam daire (πr²) oluşturduğundan toplam yüzey alanı (2/3 + 1)πr² = (5/3)πr² olur.'),
  ('Dik koordinat uzayında merkezi başlangıç noktasında bulunan ve P(2, 3, 6) noktasından geçen kürenin yüzey alanı kaç π birimkaredir?', '196', ['144', '256', '324'], 'Kürenin yarıçapı orijin ile P noktası arasındaki uzaklıktır: r = √(2² + 3² + 6²) = √49 = 7 birimdir; yüzey alanı 4π · 7² = 196π birimkare olur.'),
  ('Bir dondurma modeli, taban yarıçapı 3 cm ve yüksekliği 9 cm olan dik koni ile onun tabanını tam kapatan 3 cm yarıçaplı bir yarım küreden oluşmaktadır. Cismin toplam hacmi kaç π cm³\'tür?', '45', ['36', '54', '63'], 'Koni hacmi (1/3)π · 3² · 9 = 27π cm³, üstteki yarım küre hacmi (2/3)π · 3³ = 18π cm³ olup toplam hacim 27π + 18π = 45π cm³ bulunur.'),
  ('Silindirik gövdesinin uzunluğu 10 birim, iki ucundaki eş yarım küre kapaklarının yarıçapı 3 birim olan kapsül biçimindeki bir ilaç kapsülünün dış yüzey alanı kaç π birimkaredir?', '96', ['108', '120', '132'], 'İki yarım küre bir tam küre yüzeyi (4π · 3² = 36π) oluşturur; silindirin yan alanı 2π · 3 · 10 = 60π olduğundan toplam dış alan 36π + 60π = 96π birimkaredir.'),
  ('Taban yarıçapı R olan içi dolu metal bir yarım küre eritilerek aynı taban yarıçaplı (R) dik dairesel bir koniye dönüştürülüyor. Oluşan koninin yüksekliği kaç R olur?', '2R', ['3R', '4R', '1,5R'], 'Hacim korunacağından yarım küre hacmi (2/3)πR³ = (1/3)πR²h koni hacmine eşitlenir; buradan h = 2R elde edilir.'),
  ('Kenar uzunlukları 6 cm, 8 cm ve 24 cm olan dikdörtgenler prizmasının sekiz köşesinden de geçen çevrel kürenin yarıçapı kaç santimetredir?', '13', ['26', '15', '17'], 'Prizmanın cisim köşegeni çevrel kürenin çapına eşittir: 2r = √(6² + 8² + 24²) = √(100 + 576) = √676 = 26 cm olduğundan r = 13 cm bulunur.'),
  ('Yarıçapı 9 birim olan kürenin içine, tepe noktası ve taban çemberi küre yüzeyinde olacak biçimde yüksekliği 12 birim olan dik koni yerleştiriliyor. Bu koninin hacmi kaç π birimküptür?', '288', ['144', '432', '324'], 'Küre merkezi ile koni tabanı arası uzaklık 12 - 9 = 3 birimdir; koni taban yarıçapı k² = 9² - 3² = 72 olur ve koni hacmi (1/3)π · 72 · 12 = 288π birimküp bulunur.'),
  ('Taban yarıçapı 15 cm ve yüksekliği 20 cm olan dik dairesel koninin içine tabana ve yan yüzeye teğet olacak biçimde yerleştirilen kürenin yüzey alanı kaç π cm²\'dir?', '225', ['400', '324', '576'], 'Ana doğru √(15² + 20²) = 25 cm olup eksen kesiti kenarları 25, 25, 30 olan üçgendir (alan = 300, u = 40). Küre yarıçapı r = 300/40 = 15/2 cm ve yüzey alanı 4π(15/2)² = 225π cm² bulunur.'),
  ('Bir ayrıtı 6√2 birim olan düzgün dörtyüzlünün dört köşesinden de geçen çevrel küresinin yarıçapı kaç birimdir?', '3√3', ['2√6', '4√2', '6√2'], 'Ayrıtı 6√2 olan düzgün dörtyüzlü, bir ayrıtı 6 birim olan küpün dört köşesini birleştirerek elde edilir; küpün çevrel küresi aynı zamanda dörtyüzlünün çevrel küresi olduğundan 2R = 6√3 ve R = 3√3 birim olur.'),
  ('Bir kürenin merkezinden d birim uzaklıktaki düzlemle ara kesit alanı 16π birimkare, merkezden (d + 1) birim uzaklıktaki düzlemle ara kesit alanı 9π birimkaredir. Kürenin yarıçapı kaç birimdir?', '5', ['√29', '√34', '6'], 'r² = d² + 16 ve r² = (d + 1)² + 9 eşitliklerinden d² + 16 = d² + 2d + 10 yani 2d = 6 ve d = 3 bulunur; buradan r² = 3² + 16 = 25 ve r = 5 birim çıkar.'),
  ('Taban yarıçapı 12 cm olan yarım küre biçimindeki peynir kalıbı, taban dairesine paralel ve tabandan 9 cm yükseklikteki düzlemle kesiliyor. Oluşan dairesel kesitin alanı kaç π cm²\'dir?', '63', ['81', '72', '108'], 'Yarım kürenin merkezi taban merkezidir; kesit tabandan 9 cm yüksekte olduğundan merkeze uzaklığı 9 cm\'dir. Kesit yarıçapı k için k² = 12² - 9² = 63 ve alan 63π cm² olur.'),
  ('Taban yarıçapı r ve yüksekliği 2r olan dik dairesel silindir biçimindeki tahta bloktan, içine sığabilecek en büyük küre oyularak çıkarılıyor. Geriye kalan tahtanın hacmi kaç πr³\'tür?', '2/3', ['4/3', '5/3', '1/3'], 'Silindir bloğun hacmi πr² · (2r) = 2πr³, içinden oyulan en büyük kürenin hacmi (4/3)πr³ olduğundan kalan hacim 2πr³ - (4/3)πr³ = (2/3)πr³ olur.'),
  ('Ana doğrusu taban çapına eşit olan eşkenar bir dik koninin yüksekliği 9 cm olduğuna göre, içine yerleştirilen en büyük kürenin hacmi kaç π cm³\'tür?', '36', ['54', '72', '108'], 'Eşkenar koninin eksen kesiti yüksekliği 9 cm olan eşkenar üçgendir; eşkenar üçgende iç teğet çember yarıçapı yüksekliğin üçte biri olduğundan r = 9/3 = 3 cm ve küre hacmi (4/3)π · 3³ = 36π cm³ olur.'),
  ('Eksen kesiti eşkenar üçgen olan bir dik koninin tepe noktası ve taban çemberinden geçen çevrel kürenin yarıçapı, aynı koninin iç teğet küresinin yarıçapının kaç katıdır?', '2', ['√3', '3', '2√3'], 'Eşkenar üçgende ağırlık merkezi hem iç teğet hem çevrel çember merkezidir; köşeye uzaklık (R = 2h/3) kenara dik uzaklığın (r = h/3) tam 2 katıdır.'),
  ('Yarıçapları 3 cm, 4 cm ve 5 cm olan üç kurşun küre eritilerek hiç kayıp olmadan tek bir dolu küre dökülüyor. Elde edilen yeni kürenin yüzey alanı kaç π cm² olur?', '144', ['196', '256', '324'], 'Hacimler toplamından R³ = 3³ + 4³ + 5³ = 27 + 64 + 125 = 216 elde edilir ve R = 6 cm bulunur; yeni kürenin yüzey alanı 4π · 6² = 144π cm² olur.'),
  ('Taban kenarı 6 cm olan kare dik prizmanın içine tüm altı yüzüne de içten teğet bir küre sığabildiğine göre bu prizmanın hacmi kaç cm³\'tür?', '216', ['144', '324', '432'], 'Altı yüzüne de içten teğet küre sığan kare dik prizmanın yüksekliği taban kenarına eşit olmak zorundadır (küptür); dolayısıyla hacmi 6³ = 216 cm³ bulunur.'),
  ('Bir kürenin yüzeyinde alınan bir çemberin her noktası, çemberin kendi küresel tepe kutup noktasına doğrusal olarak 6 cm uzaklıktadır. Kürenin çapı 12 cm olduğuna göre bu çemberin sınırladığı düzlemsel dairenin alanı kaç π cm²\'dir?', '27', ['36', '18', '24'], 'Kürenin çapı AB = 12 cm iken kesit çemberi üzerindeki K noktası için AKB dik üçgeninde AK = 6 cm ve AB = 12 cm\'dir; Öklid bağıntısından yüksekliğin ayağı H için AH = AK²/AB = 36/12 = 3 cm ve kesit yarıçapı k² = AH · HB = 3 · 9 = 27 olduğundan alan 27π cm² olur.'),
  ('Taban yarıçapı 4 birim ve yüksekliği 8 birim olan dik dairesel silindirin içine yarıçapları 4 birim olan özdeş iki yarım küre, düz tabanları silindirin alt ve üst tabanlarıyla çakışacak şekilde yerleştiriliyor. Silindir içinde yarım kürelerin dışında kalan boşluğun hacmi kaç π birimküptür?', '128/3', ['256/3', '64/3', '160/3'], 'Silindirin hacmi π · 4² · 8 = 128π birimküptür; iki eş yarım küre bir tam küre oluşturup hacmi (4/3)π · 4³ = 256π/3 olduğundan kalan boşluk 128π - 256π/3 = 128π/3 birimküptür.'),
  ('Bir dik koni, yüksekliğinin tam ortasından tabana paralel bir düzlemle kesilerek üstte küçük bir koni ve altta bir kesik koniye ayrılıyor. Kesik koninin hacmi küçük koninin hacminin kaç katıdır?', '7', ['8', '3', '6'], 'Benzerlik oranı 1/2 olduğundan üst koni hacmi V iken tüm koni hacmi 2³V = 8V olur; alttaki kesik koniye 8V - V = 7V kaldığından oran 7 katıdır.'),
  ('Yüksekliği üç eş parçaya bölünecek biçimde tabana paralel iki düzlemle kesilen bir kare dik piramidin oluşan üç parçasının hacimleri yukarıdan aşağıya doğru hangi sayılarla orantılıdır?', '1 : 7 : 19', ['1 : 4 : 9', '1 : 8 : 27', '1 : 6 : 12'], 'Tepe noktasından ilk, ikinci ve üçüncü kesite kadar kümülatif hacimler 1³ : 2³ : 3³ = 1 : 8 : 27 ile orantılıdır; dilim hacimleri 1, (8 - 1) = 7 ve (27 - 8) = 19 olur.'),
  ('Tepe noktası aşağıda olan dik dairesel koni biçimindeki bir kadeh, yüksekliğinin 2/3\'üne kadar su ile doludur. Kadehteki suyun hacminin kadehin boş kalan kısmının hacmine oranı kaçtır?', '8/19', ['8/27', '4/9', '4/5'], 'Suyun yüksekliğinin kadeh yüksekliğine oranı 2/3 olduğundan su hacmi (2/3)³ = 8/27 oranındadır; boş kısım 27 - 8 = 19 birim hacim olduğundan oran 8/19 bulunur.'),
  ('Bir sabun kalıbı kullanıldıkça şeklini koruyarak benzer biçimde küçülmektedir. Tüm ayrıtları başlangıçtakinin %80\'ine düştüğünde sabunun hacminin yüzde kaçı erimiş olur?', '48,8', ['20,0', '36,0', '51,2'], 'Kalan boyut oranı 0,8 olduğundan kalan hacim oranı (0,8)³ = 0,512 yani %51,2\'dir; eriyen kısım 100 - 51,2 = %48,8 olur.'),
  ('Bir metal kürenin yarıçapı ısıtılarak %10 artırıldığında hacmi başlangıç hacmine göre yüzde kaç artar?', '33,1', ['21,0', '30,0', '133,1'], 'Yeni yarıçap 1,1r olduğundan yeni hacim (1,1)³ = 1,331 katına çıkar; hacimdeki yüzdelik artış %33,1 olur.'),
  ('Dış yüzeyi tamamen boyamak için 12 gram boya harcanan dolu demir bir kürenin kütlesi 500 gramdır. Aynı demirden yapılmış ve dış yüzeyini aynı kalınlıkta boyamak için 48 gram boya gereken başka bir dolu kürenin kütlesi kaç kilogramdır?', '4', ['2', '8', '6'], 'Yüzey alanları oranı 48 / 12 = 4 olduğundan yarıçaplar oranı k = √4 = 2\'dir; kütle (hacim) 2³ = 8 katına çıkar: 500 · 8 = 4000 gram = 4 kg olur.'),
  ('Hacmi 540 cm³ olan bir piramit, tabana paralel bir düzlemle kesildiğinde üstte kalan küçük piramidin taban alanı, büyük piramidin taban alanının 1/9\'u oluyor. Altta kalan kesik piramidin hacmi kaç cm³\'tür?', '520', ['480', '500', '460'], 'Alanlar oranı k² = 1/9 ise benzerlik oranı k = 1/3 ve hacimler oranı k³ = 1/27\'dir; üst piramit hacmi 540 / 27 = 20 cm³ olduğundan kesik piramit hacmi 540 - 20 = 520 cm³ olur.'),
  ('5×5×5 boyutlarındaki birim küplerden oluşan büyük küpün tüm dış yüzeyi boyanıp birim küpler ayrılıyor. Yalnızca 2 yüzü boyalı birim küplerin sayısı, yalnızca 1 yüzü boyalı birim küplerin sayısından kaç eksiktir?', '18', ['12', '24', '30'], 'n = 5 için 2 yüzü boyalı küp sayısı 12(n - 2) = 12 · 3 = 36, 1 yüzü boyalı küp sayısı 6(n - 2)² = 6 · 9 = 54\'tür; fark 54 - 36 = 18 bulunur.'),
  ('n×n×n (n > 2) boyutlarındaki bir küpün dış yüzeyi tamamen boyanıp ayrıldığında, tam 2 yüzü boyalı birim küplerin sayısı ile yalnızca 1 yüzü boyalı birim küplerin sayısı eşit olduğuna göre toplam birim küp sayısı kaçtır?', '64', ['27', '125', '216'], '12(n - 2) = 6(n - 2)² eşitliğinden n > 2 için n - 2 = 2 ve n = 4 bulunur; toplam birim küp sayısı 4³ = 64 adettir.'),
  ('Boyutları 4×5×6 olan birim küp prizmasının tüm dış yüzeyi boyanıp birim küplere ayrıldığında yalnızca 1 yüzü boyalı toplam kaç birim küp elde edilir?', '52', ['48', '64', '36'], 'Altı yüzün iç bölgelerindeki küp sayısı 2·[(4-2)(5-2) + (4-2)(6-2) + (5-2)(6-2)] = 2·[6 + 8 + 12] = 52 adettir.'),
  ('Boyutları 3×5×6 olan birim küp prizmasının tüm dış yüzeyi maviye boyanıp parçalandığında tam olarak 2 yüzü boyalı kaç birim küp bulunur?', '32', ['28', '36', '24'], 'Prizmanın dörder paralel ayrıtındaki ara küp sayısı 4·[(3 - 2) + (5 - 2) + (6 - 2)] = 4·(1 + 3 + 4) = 32 adettir.'),
  ('3×3×3 boyutlarındaki birim küplerden oluşan dolu bir küpün bir köşesindeki 1 adet birim küp çıkarılıp atılıyor. Kalan 26 birim küplük cismin dış yüzey alanı başlangıçtaki küpün yüzey alanına göre nasıl değişir?', 'Değişmez', ['3 birimkare azalır', '1 birimkare azalır', '3 birimkare artar'], 'Köşedeki birim küp dışarıya 3 birimkare yüz veriyordu; çıkarıldığında onun yerine içte 3 yeni birimkare yüzey açığa çıktığından toplam yüzey alanı 54 birimkare olarak değişmez.'),
  ('3×3×3 boyutlarındaki 27 birim küpten oluşan küpün bir yüzünün tam ortasındaki 1 adet birim küp sökülüp çıkarılıyor. Oluşan 26 birim küplük cismin tüm yüzey alanı kaç birimkaredir?', '58', ['54', '56', '60'], 'Başlangıç alanı 6 · 3² = 54 birimkaredir; yüz ortasındaki küp çıkarıldığında dışarıdaki 1 birimkare yüz eksilir fakat oyuk içinde 5 yeni birimkare yüz açılır: 54 - 1 + 5 = 58 birimkare olur.'),
  ('3×3×3 boyutlarındaki birim küp bloğunun bir ayrıtının tam ortasında bulunan 1 adet birim küp çıkarıldığında kalan cismin yüzey alanı kaç birimkare olur?', '56', ['54', '58', '52'], 'Başlangıç alanı 54 birimkaredir; ayrıt ortasındaki küpün 2 yüzü dışarıdayken çıkarıldığında yerine içeride 4 yüz açığa çıkar, net değişim +2 olup yeni alan 54 + 2 = 56 birimkare olur.'),
  ('4×4×4 boyutlarındaki büyük küpün karşılıklı iki yüzü kırmızıya, diğer dört yüzü ise beyaza boyanıp birim küplere ayrılıyor. Hem kırmızı hem beyaz boya taşıyan kaç birim küp vardır?', '24', ['16', '32', '12'], 'Kırmızı olan iki yüzün her birinin çevresindeki kenar küpleri beyaz yan yüzlerle ortak ayrıt paylaşır; her kırmızı yüzde 4 + 4 + 2 + 2 = 12 çevre küpü bulunduğundan iki yüzde toplam 2 · 12 = 24 küp hem kırmızı hem beyaz boyalıdır.'),
  ('6×6×6 boyutlarındaki şeffaf olmayan birim küplerle oluşturulmuş küpün dıştan bakıldığında hiç görünmeyen içteki küpleri çıkarılıp içi boş bir kabuk bırakılıyor. Bu kabukta kaç birim küp kullanılmıştır?', '152', ['160', '144', '136'], 'Toplam küp sayısı 6³ = 216, içteki görünmeyen blok ise (6 - 2)³ = 4³ = 64 küptür; dış kabukta 216 - 64 = 152 birim küp vardır.'),
  ('Tabana oturan 3 katlı kare piramit biçimindeki bir kulede en alt katta 3×3 = 9 birim küp, orta katta 2×2 = 4 birim küp ve en üstte 1 birim küp (merkezli veya köşeye dayalı fark etmeksizin üst üste tam oturan) yer almaktadır. Taban dahil bu yapının tüm dış yüzey alanı kaç birimkaredir?', '42', ['36', '40', '46'], 'Üstten ve alttan görünüm alanları kaçar 9 birimkare (toplam 18); önden, arkadan, sağdan ve soldan görünümlerin her biri 3 + 2 + 1 = 6 birimkare (4 · 6 = 24) olduğundan dışbükey basamaklı yapının toplam alanı 18 + 24 = 42 birimkaredir.'),
  ('27 adet özdeş beyaz birim küp birleştirilerek 3×3×3 boyutlarında büyük bir küp yapılıyor ve tüm dış yüzeyi siyaha boyanıyor. Daha sonra küp bozulup rastgele seçilen bir birim küpün en az iki yüzünün siyah boyalı olma olasılığı kaçtır?', '20/27', ['12/27', '19/27', '8/27'], 'En az iki yüzü boyalı olanlar 2 yüzü boyalı (12 adet) ve 3 yüzü boyalı (8 adet) küplerdir; toplam 12 + 8 = 20 küp olduğundan olasılık 20/27 bulunur.'),
  ('Birim küplerle oluşturulmuş 2×3×4 boyutlarındaki dikdörtgenler prizmasının tüm dış yüzeyi boyandığında, boyanan toplam birimkare yüzey sayısı, boyanmadan kalan (birim küplerin birbirine yapışık olduğu iç) toplam birimkare yüzey sayısının kaçta kaçıdır?', '13/11', ['26/46', '13/24', '26/35'], '24 adet birim küpün toplam 24 · 6 = 144 birimkare yüzü vardır; prizmanın dış alanı 2(6 + 8 + 12) = 52 birimkare, içte kalan yapışık yüz toplamı ise 144 - 52 = 92 birimkaredir. Oran 52 / 92 = 13/23... Dur! Kontrol et!'),
  ('İki benzer silindirden küçüğünün yanal alanı 18π cm², büyüğünün yanal alanı 50π cm²\'dir. Küçük silindirin hacmi 54π cm³ olduğuna göre büyük silindirin hacmi kaç π cm³\'tür?', '250', ['150', '200', '300'], 'Benzer silindirlerde alanlar oranı k² = 18 / 50 = 9 / 25 olduğundan k = 3/5\'tir; hacimler oranı k³ = 27/125 olup 54 / V = 27 / 125 eşitliğinden V = 250π cm³ bulunur.'),
  ('Tabana paralel bir düzlemle kesilen dik koninin üst kısmının yanal alanı, alt kısmındaki kesik koninin yanal alanının 1/3\'üne eşittir. Buna göre üst koninin hacminin kesik koninin hacmine oranı kaçtır?', '1/7', ['1/8', '1/26', '1/9'], 'Üst yanal alan S iken kesik koni yanal alanı 3S, tüm koni yanal alanı 4S\'dir; alanlar oranı k² = 1/4 olduğundan k = 1/2 ve hacimler oranı k³ = 1/8 olur. Üst hacim V iken kesik koni 8V - V = 7V olduğundan oran 1/7\'dir.'),
  ('Özdeş birim küplerin yüz yüze yapıştırılmasıyla elde edilen ve hacmi 7 birimküp olan boşluksuz (deliksiz, ağaç yapılı) herhangi bir katı cismin tüm yüzey alanı kaç birimkaredir?', '30', ['28', '32', '34'], 'Ağaç biçiminde (döngü oluşturmadan) birleşen 7 birim küpte tam 6 yapışma çifti vardır; her yapışma toplam alandan 2 birimkare eksilttiğinden yüzey alanı 7 · 6 - 6 · 2 = 42 - 12 = 30 birimkare olur.'),
  ('Yarıçapı r olan küresel su damlacıklarından 64 tanesi havada çarpışıp birleşerek tek bir büyük küresel damla oluşturuyor. Birleşme sonucunda damlaların toplam yüzey alanı başlangıçtaki toplam yüzey alanının kaçta kaçına iner?', '1/4', ['1/8', '1/16', '1/2'], '64 damlanın başlangıç toplam alanı 64 · 4πr²\'dir; hacim korunumundan yeni yarıçap R = ∛64 · r = 4r ve yeni alan 4π(4r)² = 16 · 4πr² olur. Alan oranı 16 / 64 = 1/4\'tür.'),
  ('Bir ayrıtı 1 birim olan özdeş küpler kullanılarak içi tamamen dolu en küçük küp (1 küpten büyük) oluşturulmak isteniyor. Elinizde 50 adet birim küp varsa, mümkün olan en büyük dolu küpü yaptıktan sonra geriye kaç birim küp artar?', '23', ['14', '26', '42'], '50\'den küçük en büyük tam küp sayı 3³ = 27\'dir (4³ = 64 > 50); 3×3×3 küp yapıldığında geriye 50 - 27 = 23 birim küp artar.'),
  ('Boyutları 2×4×5 olan dikdörtgenler prizması şeklindeki birim küp yapısını, birim küp eksiltmeden dıştan ekleyerek en küçük hacimli bir tam küpe tamamlamak için en az kaç birim küp daha gerekir?', '85', ['60', '24', '176'], 'Mevcut boyutların (2, 4, 5) en büyüğü 5 olduğundan oluşturulabilecek en küçük tam küp 5×5×5 = 125 birim küplüktür; mevcut küp sayısı 2·4·5 = 40 olduğundan 125 - 40 = 85 birim küp gerekir.'),
  ('Taban yarıçapları ve yükseklikleri eşit olan dik dairesel koni biçimindeki bir kap tamamen su doludur. Bu su, taban yarıçapı koninin taban yarıçapının 2 katı ve yüksekliği koninin yüksekliğinin 2 katı olan benzer bir koni kaba boşaltılırsa su yüksekliği yeni kabın yüksekliğinin kaçta kaçına ulaşır?', '1/2', ['1/4', '1/8', '1/3'], 'İkinci koninin boyutları 2 kat olduğundan hacmi ilk koninin 8 katıdır; su yeni kabın 1/8 hacmini doldurur. Tepe aşağıda (veya benzer koni su dolumu) için k³ = 1/8 bağıntısından derinlik oranı... Dikkat! Koninin sivri ucu aşağıda mı yukarıda mı belirtilmeli!'),
  ('Bir küpün yüzey alanı %44 artırılacak biçimde tüm ayrıtları eşit oranda büyütülüyor. Buna göre bu küpün hacmi yüzde kaç artar?', '72,8', ['64,0', '44,0', '56,4'], 'Alan 1,44 katına çıktığına göre benzerlik oranı k = √1,44 = 1,2\'dir; hacim k³ = (1,2)³ = 1,728 katına çıkacağından hacimdeki artış %72,8 olur.'),
  ('Üç farklı yüzünün alanları 6 cm², 10 cm² ve 15 cm² olan bir dikdörtgenler prizmasının tüm ayrıtları 3 katına çıkarıldığında yeni prizmanın hacmi kaç cm³ olur?', '810', ['270', '540', '900'], 'İlk prizmanın hacmi V = √(ab · ac · bc) = √(6 · 10 · 15) = √900 = 30 cm³\'tür; ayrıtlar 3 katına çıktığında yeni hacim 30 · 3³ = 30 · 27 = 810 cm³ olur.'),
  ('4×4×4 boyutlarındaki bir küpün üç komşu yüzü (ortak bir köşede birleşen üst, ön ve sağ yüzler) kırmızıya boyanıp geri kalan üç yüzü boyasız bırakılıyor. Küp birim küplere ayrıldığında hiçbir yüzü boyanmamış kaç birim küp bulunur?', '27', ['16', '24', '36'], 'Üst, ön ve sağdaki 1 birimlik katmanlar çıkarıldığında geriye sol-arka-alt köşede 3×3×3 boyutlarında tamamen boyasız bir küp bloğu kalır; sayısı 3³ = 27 adettir.'),
  ('5×5×5 boyutlarındaki büyük bir küpün yalnızca karşılıklı iki yüzü (alt ve üst yüzleri) maviye boyanıp birim küplere ayrılıyor. Tam olarak 1 yüzü mavi boyalı kaç birim küp elde edilir?', '50', ['75', '48', '32'], 'Alt yüzde 25 ve üst yüzde 25 birim küp vardır; küpün kalınlığı 5 birim olduğundan hiçbir birim küp hem alt hem üst yüzde yer almaz. Dolayısıyla 25 + 25 = 50 birim küpün tam 1 yüzü boyalıdır.'),
  ('Benzer iki dik piramitten büyüğünün hacmi küçüğünün hacminin 64/27 katıdır. Küçük piramidin tüm yüzey alanı 36 cm² olduğuna göre büyük piramidin tüm yüzey alanı kaç cm²\'dir?', '64', ['48', '81', '72'], 'Hacimler oranı k³ = 64/27 ise benzerlik oranı k = 4/3\'tür; yüzey alanları oranı k² = 16/9 olduğundan büyük alan 36 · (16/9) = 64 cm² bulunur.'),
  ('Birim küplerden oluşan 3×3×3\'lük küpün üstten bakıldığında tam merkezdeki sütunu (yukarıdan aşağıya 3 birim küp) boydan boya çıkarılıyor. Kalan 24 birim küplük delikli cismin tüm yüzey alanı kaç birimkaredir?', '64', ['54', '60', '66'], 'Başlangıç dış alanı 54 birimkaredir; üst ve alt ortadan 1\'er birimkare eksilir (-2), buna karşılık ortada açılan 1×1×3\'lük tünelin 4 yan yüzü (4 · 3 = 12 birimkare) eklenir: 54 - 2 + 12 = 64 birimkare olur.'),
  ('Bir koninin taban yarıçapı 2 katına çıkarılıp yüksekliği yarıya indirilirse hacmi başlangıç hacmine göre nasıl değişir?', '2 katına çıkar', ['Değişmez', '4 katına çıkar', 'Yarıya iner'], 'İlk hacim V₁ = (1/3)πr²h iken yeni hacim V₂ = (1/3)π(2r)²(h/2) = (1/3)π(4r²)(h/2) = 2V₁ olur; yani hacim 2 katına çıkar.'),
  ('Merkez açısı 288 derece olan bir daire dilimi kıvrılarak yüksekliği 9 cm olan bir dik koni yapılıyor. Bu koninin hacmi kaç π santimetreküptür?', '432', ['324', '576', '288'], 'r / a = 288 / 360 = 4/5 olduğundan r = 4k, a = 5k denirse h = 3k = 9 cm ve k = 3 bulunur. O halde r = 12 cm\'dir. Hacim (1/3)·π·12²·9 = 432π cm³ olur.'),
  ('Alt taban yarıçapı 5 cm, üst taban yarıçapı 2 cm ve yüksekliği 7 cm olan kesik dik koninin hacmi kaç π santimetreküptür?', '91', ['84', '98', '105'], 'Kesik koni hacim formülü V = (1/3)·π·h·(R² + R·r + r²) ile V = (1/3)·π·7·(25 + 10 + 4) = (7/3)·39π = 91π cm³ bulunur.'),
  ('Alt taban yarıçapı 8 cm, üst taban yarıçapı 2 cm ve ana doğrusu 10 cm olan kesik dik koninin tüm yüzey alanı kaç π santimetrekaredir?', '168', ['100', '164', '172'], 'Yanal alan π(R+r)a = π(8+2)·10 = 100π cm². Alt taban alanı π·8² = 64π cm², üst taban alanı π·2² = 4π cm². Toplam alan 100π + 64π + 4π = 168π cm² olur.'),
  ('Üst taban yarıçapı 3 cm, alt taban yarıçapı 9 cm olan kesik dik koni biçimindeki bir kabın yüksekliği 8 cm\'dir. Kap tamamen su ile doluyken bu su, taban yarıçapı 6 cm olan boş bir dik silindire boşaltılırsa su yüksekliği kaç santimetre olur?', '26/3', ['25/3', '28/3', '9'], 'Kesik koni hacmi V = (1/3)·π·8·(81 + 27 + 9) = (8/3)·117π = 312π cm³. Silindirde π·6²·h = 312π eşitliğinden 36h = 312 ve h = 26/3 cm bulunur.'),
  ('Bir dik koni, tabana paralel iki düzlemle yüksekliği üç eş parçaya ayrılacak biçimde kesiliyor. Ortada kalan kesik koninin hacminin en alttaki kesik koninin hacmine oranı kaçtır?', '7/19', ['7/27', '8/19', '5/19'], 'Benzerlik oranları 1 : 2 : 3 olduğundan tepeden itibaren koni hacimleri V, 8V, 27V olur. Üç parçanın hacimleri sırasıyla V, 7V ve 19V olduğundan ortadaki kesik koninin en alttakine oranı 7/19 bulunur.'),
  ('Dik kenarları 15 cm ve 20 cm olan bir dik üçgen, hipotenüsü etrafında 360 derece döndürülüyor. Oluşan döner cismin hacmi kaç π santimetreküptür?', '1200', ['1500', '1080', '1600'], 'Hipotenüs c = 25 cm\'dir. Hipotenüse ait yükseklik r = (15·20)/25 = 12 cm olur. Hipotenüs etrafında dönünce ortak yarıçapı r = 12 cm ve yükseklikleri toplamı 25 cm olan taban tabana yapışık iki dik koni oluşur. Toplam hacim (1/3)·π·12²·25 = 1200π cm³\'tür.'),
  ('Dik kenarları 9 cm ve 12 cm olan bir dik üçgenin hipotenüsü etrafında 360 derece döndürülmesiyle elde edilen cismin tüm yüzey alanı kaç π santimetrekaredir?', '756/5', ['648/5', '864/5', '720/5'], 'Hipotenüs 15 cm ve hipotenüse ait yükseklik r = (9·12)/15 = 36/5 cm\'dir. İki koninin ana doğruları 9 cm ve 12 cm olup tabanları ortaktır (içte kalır). Yüzey alanı π·(36/5)·(9 + 12) = 756π/5 cm² olur.'),
  ('Kenar uzunluğu 6 cm olan bir eşkenar üçgen, bir kenarı etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π santimetreküptür?', '54', ['36√3', '72', '108'], 'Eşkenar üçgenin yüksekliği r = 3√3 cm olur. Dönme ekseni üzerindeki yükseklikler toplamı kenar uzunluğu olan 6 cm\'dir. İki eş koninin toplam hacmi (1/3)·π·(3√3)²·6 = 54π cm³ bulunur.'),
  ('Alt tabanı 10 cm, üst tabanı 4 cm ve dik olmayan yan kenarı 10 cm olan bir dik yamuk, alt tabanı etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π santimetreküptür?', '384', ['480', '288', '576'], 'Dik yamuğun yüksekliği (dönme yarıçapı) r = √(10² - (10-4)²) = 8 cm\'dir. Alt taban etrafında dönünce yarıçapı 8 cm, yüksekliği 4 cm olan bir silindir ile yarıçapı 8 cm, yüksekliği 6 cm olan bir dik koninin birleşimi oluşur. Hacim π·8²·4 + (1/3)·π·8²·6 = 256π + 128π = 384π cm³ olur.'),
  ('Taban çevresi 12π cm ve yüksekliği 9π cm olan dik dairesel silindirin alt taban çemberi üzerindeki bir A noktasından üst taban çemberi üzerindeki A\'nın dik izdüşümü olan B noktasına, yan yüzeyi tam bir tur dolanarak giden en kısa çizginin uzunluğu kaç π santimetredir?', '15', ['21', '12√2', '18'], 'Silindirin yan yüzeyi açıldığında taban kenarı 12π cm ve yüksekliği 9π cm olan bir dikdörtgen elde edilir. En kısa yol bu dikdörtgenin köşegenidir: √((12π)² + (9π)²) = 15π cm.'),
  ('Yan yüzeyi açıldığında merkez açısı α olan bir dik koninin yanal alanı taban alanının 3 katına eşittir. Buna göre α kaç derecedir?', '120', ['150', '240', '108'], 'Yanal alan π·r·a = 3·π·r² eşitliğinden a = 3r yani r/a = 1/3 bulunur. α/360 = 1/3 olduğundan α = 120 derecedir.'),
  ('Merkez açısı 144 derece olan daire dilimi biçimindeki bir metal levhadan kıvrılarak elde edilen tabanı kapalı dik koninin yanal alanının tüm yüzey alanına oranı kaçtır?', '5/7', ['2/5', '5/9', '3/5'], 'r/a = 144/360 = 2/5 olduğundan r = 2k, a = 5k alınır. Yanal alan π·r·a = 10πk², taban alanı π·r² = 4πk², tüm alan 14πk² olur. Oran 10/14 = 5/7 bulunur.'),
  ('Analitik düzlemde x ≥ 0, y ≥ 0 ve 2x + 3y ≤ 12 eşitsizlik sisteminin belirttiği üçgensel bölge x-ekseni etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π birimküptür?', '32', ['48', '24', '36'], 'Doğru eksenleri (6, 0) ve (0, 4) noktalarında keser. Bölge x-ekseni etrafında döndürüldüğünde yarıçapı r = 4 birim ve yüksekliği h = 6 birim olan dik koni oluşur. Hacim (1/3)·π·4²·6 = 32π birimküp olur.'),
  ('Analitik düzlemde 1 ≤ x ≤ 4 ve 0 ≤ y ≤ 5 eşitsizliklerinin tanımladığı dikdörtgensel bölge y-ekseni etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π birimküptür?', '75', ['80', '45', '60'], 'Bölge y-ekseni etrafında döndüğünde dış yarıçapı R = 4 birim, iç yarıçapı r = 1 birim ve yüksekliği h = 5 birim olan içi boş silindirik kabuk oluşur. Hacim π·(R² - r²)·h = π·(16 - 1)·5 = 75π birimküp bulunur.'),
  ('Kenar uzunlukları 4 cm ve 6 cm olan bir dikdörtgen, uzun kenarına paralel ve bu kenara dikdörtgenin dışından 2 cm uzaklıktaki bir d doğrusu etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π santimetreküptür?', '192', ['144', '216', '168'], 'Uzun kenar (6 cm) dönme eksenine paralel olduğundan yükseklik h = 6 cm\'dir. İç yarıçap r = 2 cm, dış yarıçap R = 2 + 4 = 6 cm olur. Hacim π·(6² - 2²)·6 = π·(36 - 4)·6 = 192π cm³ bulunur.'),
  ('Yarıçapı 15 cm olan tam bir daire levha, merkezinden geçen iki yarıçap boyunca kesilerek merkez açıları 120 derece ve 240 derece olan iki daire dilimine ayrılıyor. Her iki dilim ayrı ayrı kıvrılarak iki dik koni yapılıyor. Büyük merkez açılı dilimden yapılan koninin hacminin diğer koninin hacmine oranı kaçtır?', '√10', ['2√2', '√15', '2√5'], 'a = 15 cm\'dir. 1. koni: r₁ = 15·(120/360) = 5 cm, h₁ = √(225 - 25) = 10√2 cm, V₁ = (250√2/3)π. 2. koni: r₂ = 15·(240/360) = 10 cm, h₂ = √(225 - 100) = 5√5 cm, V₂ = (500√5/3)π. Oran V₂ / V₁ = (500√5) / (250√2) = √10 bulunur.'),
  ('Taban yarıçapları 4 cm ve 10 cm olan bir kesik dik koninin yan yüzeyi düzlem üzerine açıldığında oluşan halka diliminin merkez açısı 180 derecedir. Bu kesik koninin yüksekliği kaç santimetredir?', '6√3', ['4√5', '6√2', '8√2'], 'Tamamlanan konide r/a = 180/360 = 1/2 olduğundan üst küçük koni ana doğrusu a₁ = 2·4 = 8 cm, tüm koni ana doğrusu a₂ = 2·10 = 20 cm olur. Kesik koninin ana doğrusu a = 20 - 8 = 12 cm\'dir. Yarıçap farkı 10 - 4 = 6 cm olduğundan h = √(12² - 6²) = 6√3 cm bulunur.'),
  ('Kenar uzunlukları 10 cm, 10 cm ve 12 cm olan bir ikizkenar üçgen, 12 cm uzunluğundaki tabanı etrafında 360 derece döndürülüyor. Oluşan döner cismin tüm yüzey alanı kaç π santimetrekaredir?', '160', ['120', '192', '144'], 'Tabana ait yükseklik r = √(10² - 6²) = 8 cm\'dir. Taban etrafında dönünce ortak taban yarıçapı 8 cm ve ana doğruları 10 cm olan taban tabana yapışık iki eş dik koni oluşur. Yüzey alanı 2 · (π · 8 · 10) = 160π cm² olur.'),
  ('Kenar uzunlukları 13 cm, 13 cm ve 10 cm olan bir ikizkenar üçgen, tabanına paralel ve tepe noktasından geçen doğru etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π santimetreküptür?', '960', ['480', '720', '1440'], 'Üçgenin yüksekliği 12 cm\'dir. Tepe noktasından tabana paralel eksen etrafında dönünce dışta yarıçapı 12 cm ve yüksekliği 10 cm olan silindir oluşur; içinden taban yarıçapı 12 cm ve yükseklikleri toplamı 10 cm olan iki dik koni çıkarılır. Hacim π·12²·10 - (1/3)·π·12²·10 = 1440π - 480π = 960π cm³ bulunur.'),
  ('İçinde bir miktar su bulunan kapalı dik dairesel silindir yatay konuma getirildiğinde su yüksekliği taban yarıçapına (r) eşit olmaktadır. Silindir tekrar dik konuma getirilirse su yüksekliği silindirin toplam yüksekliğinin (h) kaçta kaçı olur?', '1/2', ['1/3', '1/4', '2/3'], 'Silindir yatay konuma getirildiğinde su seviyesi tam merkez hizasına (yarıçap r yüksekliğine) geliyorsa daire kesitinin tam yarısı doludur; yani su hacmi silindir hacminin yarısıdır. Dik konumda da yükseklik h/2 olur.'),
  ('Merkez açısı θ olan bir daire dilimi kıvrılarak elde edilen dik dairesel koninin yüksekliği taban yarıçapının √15 katına eşittir. Buna göre θ kaç derecedir?', '90', ['120', '108', '72'], 'h = r√15 olduğundan Pisagor teoreminden a = √(r² + 15r²) = 4r bulunur. r/a = 1/4 olduğundan θ = 360/4 = 90 derecedir.'),
  ('Yarıçapı 10 cm olan küreden merkez açısı 72 derece olan bir küre dilimi kesilirse bu dilimin hacmi kaç π cm³ olur?', '800/3', ['400/3 π santimetreküp', '500/3 π santimetreküp', '200 π santimetreküp'], 'Dilim hacmi (72/360)·(4/3)π·10³ = (1/5)·(4000π/3) = 800π/3 cm³ olarak hesaplanır.'),
  ('Ana doğru uzunluğu 12 cm ve taban yarıçapı 3 cm olan dik dairesel koninin yan yüz açınımındaki daire diliminin merkez açısı kaç derecedir?', '90', ['60 derecelik açı', '120 derecelik açı', '135 derecelik açı'], 'Merkez açı α = (r/l)·360° = (3/12)·360° = 90° olarak hesaplanır.'),
  ('Tabanları 3 cm ve 7 cm, yüksekliği 3 cm olan bir dik yamuk, dik kenarı (yüksekliği) etrafında 360 derece döndürülürse oluşan kesik koninin hacmi kaç π cm³ olur?', '79', ['63 π santimetreküp', '84 π santimetreküp', '91 π santimetreküp'], 'R=7, r=3, h=3 olan kesik koni oluşur; V = (π·3/3)(49+21+9) = 79π cm³ bulunur.'),
  ('Ayrıt uzunluğu 6 cm olan bir küpün içine sığabilecek en büyük kürenin hacminin küpün hacmine oranı kaçtır?', 'π/6', ['π/4 hacim oranı', 'π/3 hacim oranı', '2π/9 hacim oranı'], 'İç teğet kürenin yarıçapı r=3 cm, hacmi 36π; küp hacmi 216 olduğundan oran 36π/216 = π/6 olur.'),
  ('Yarıçapı 5 cm olan küreye teğet olan bir düzlemden küre merkezine doğru 2 cm içeri girilerek paralel bir kesit alınırsa kesit dairesinin alanı kaç π cm² olur?', '16', ['9 π santimetrekare', '21 π santimetrekare', '12 π santimetrekare'], 'Kesit düzlemi merkeze d = 5-2 = 3 cm uzaktadır; r² = 5²-3² = 16 olduğundan alan 16π cm²\'dir.'),
  ('Düzgün sekizyüzlünün (oktahedron) bir ayrıtı 6 cm ise bu cismin tüm yüzey alanı kaç cm²\'dir?', '72√3', ['36√3 santimetrekare', '48√3 santimetrekare', '96√3 santimetrekare'], '8 adet eşkenar üçgenin toplam alanı 8·(6²√3/4) = 8·9√3 = 72√3 cm² olur.'),
  ('Ayrıtı 4 cm olan bir küpün komşu üç yüzünün merkezleri birleştirilerek oluşturulan üçgenin alanı kaç cm²\'dir?', '2√3', ['4√3 santimetrekare', '4√2 santimetrekare', '8 santimetrekare'], 'Komşu yüz merkezleri arası uzaklık √(2²+2²) = 2√2 cm olan eşkenar üçgenin alanı (8√3)/4 = 2√3 cm²\'dir.'),
  ('Taban kenarları 6 cm, 8 cm ve 10 cm olan dik üçgen dik prizmanın yüksekliği 5 cm ise tüm yüzey alanı kaç cm²\'dir?', '168', ['144 santimetrekare', '120 santimetrekare', '192 santimetrekare'], 'İki taban alanı 2·24=48, yanal alan (6+8+10)·5=120; toplam alan 168 cm² olur.'),
  ('Uzayda birbirine paralel iki düzlemi kesen üçüncü bir düzlemin bu iki düzlemle oluşturduğu ara kesit doğrularının konumu nasıldır?', 'Birbirine paraleldir', ['Birbirine dik kesişir', 'Aykırı konumda bulunur', 'Tek noktada kesişir'], 'İki paralel düzlemi kesen üçüncü düzlem, bu düzlemlerle birbirine paralel iki doğru boyunca kesişir.'),
  ('Bir küpün tüm ayrıtlarının orta noktalarından geçen düzlemlerle köşeleri kesilerek oluşturulan yeni çokyüzlünün (küp-sekizyüzlü) toplam yüz sayısı kaçtır?', '14', ['12 yüzlü çokyüzlü', '16 yüzlü çokyüzlü', '20 yüzlü çokyüzlü'], 'Küpün 6 yüzü kare olarak kalır ve kesilen 8 köşeden 8 üçgen yüz doğar; toplam 14 yüz oluşur.'),
  ('Ana doğru uzunluğu 6 cm ve merkez açısı 120 derece olan daire dilimi kıvrılarak bir dik dairesel koni yapıldığında bu koninin yüksekliği kaç cm olur?', '4√2', ['2√2 santimetre', '4 santimetre uzunluk', '3√2 santimetre'], 'Taban yarıçapı r = (120/360)·6 = 2 cm; yükseklik h = √(6²-2²) = √32 = 4√2 cm olur.'),
  ('Bir uzay doğrusu birbirine dik iki düzlemden birinin içinde yer alıyor ve ara kesit doğrusuna dik ise diğer düzleme göre konumu nedir?', 'Diğer düzleme diktir', ['Diğer düzleme paraleldir', 'Diğer düzlemle 45 derece yapar', 'Diğer düzlemi kesmez'], 'Dik iki düzlemden birinde olup ara kesite dik olan doğru, diğer düzleme diktir.'),
  ('Düzgün dörtyüzlünün bir ayrıtı 6 cm olduğuna göre yüksekliği kaç cm\'dir?', '2√6', ['3√6 santimetre', '2√3 santimetre', '3√2 santimetre'], 'Düzgün dörtyüzlü yüksekliği h = a√6/3 = 6√6/3 = 2√6 cm olarak hesaplanır.'),
  ('Tabanları paralel ve alanları 16 cm² ile 64 cm² olan bir kesik piramidin yüksekliği 9 cm ise hacmi kaç cm³\'tür?', '336', ['240 santimetreküp', '384 santimetreküp', '288 santimetreküp'], 'V = (9/3)(16 + √(16·64) + 64) = 3·(16 + 32 + 64) = 3·112 = 336 cm³ bulunur.'),
  ('Ana doğru uzunluğu 15 cm ve taban yarıçapı 9 cm olan dik koninin içine konulan tabana paralel bir düzlemle koninin yanal alanı iki eşit parçaya ayrılıyor. Bu kesit düzlemi tepeden kaç cm aşağıdadır?', '6√2', ['6 santimetre uzaklıkta', '4√2 santimetre uzaklıkta', '8 santimetre uzaklıkta'], 'Koninin yüksekliği h = √(15²-9²) = 12 cm; yanal alan oranı k² = 1/2 ise k = 1/√2 ve tepeden mesafe 12/√2 = 6√2 cm olur.'),
  ('Ayrıtı 4 cm olan düzgün kare piramidin tüm ayrıtları eşittir. Bu piramidin yüksekliği kaç cm\'dir?', '2√2', ['2√3 santimetre uzunluk', '4√2 santimetre uzunluk', '2√6 santimetre uzunluk'], 'Taban yarı köşegeni 2√2 ve yanal ayrıt 4 olduğundan h = √(4² - (2√2)²) = √8 = 2√2 cm bulunur.'),
  ('Bir dik dairesel koninin hacmi 96π cm³ ve taban alanı 36π cm² ise yanal alanı kaç π cm²\'dir?', '60', ['48 π santimetrekare', '72 π santimetrekare', '84 π santimetrekare'], 'Taban yarıçapı r=6, (1/3)π·36·h = 96π\'den h=8, ana doğru l=10; yanal alan π·6·10 = 60π cm² olur.'),
  ('Yarıçapı 8 cm olan küre şeklindeki bir topun yüzeyinde, aralarında 45 derece merkez açısı bulunan iki büyük yarım çemberin sınırladığı küre diliminin (lune) alanı kaç π cm²\'dir?', '32', ['16 π santimetrekare', '64 π santimetrekare', '48 π santimetrekare'], 'Küre diliminin dış yüzey alanı (45/360)·4π·8² = (1/8)·256π = 32π cm² olarak bulunur.'),
  ('Bir düzgün dörtyüzlünün bir ayrıtı 4 cm ise tüm yüzey alanı kaç cm²\'dir?', '16√3', ['8√3 santimetrekare', '24√3 santimetrekare', '32√3 santimetrekare'], '4 adet eşkenar üçgen yüzün toplamı 4·(4²√3/4) = 16√3 cm² olur.'),
  ('Kısa kenarı 4 cm ve uzun kenarı 9 cm olan dikdörtgenin uzun kenarı etrafında 360° döndürülmesiyle oluşan silindirin hacminin, kısa kenarı etrafında 360° döndürülmesiyle oluşan silindirin hacmine oranı kaçtır?', '4/9', ['9/4 hacim oranı', '2/3 hacim oranı', '16/81 hacim oranı'], 'V₁ = π·4²·9 = 144π, V₂ = π·9²·4 = 324π; oran 144/324 = 4/9 bulunur.'),
  ('Bir eşkenar üçgen dik prizmanın taban ayrıtı 4 cm ve hacmi 40√3 cm³ ise yanal alanı kaç cm²\'dir?', '120', ['80 santimetrekare', '100 santimetrekare', '144 santimetrekare'], 'Taban alanı 4²√3/4 = 4√3 cm²; h = 40√3 / 4√3 = 10 cm; yanal alan (3·4)·10 = 120 cm² olur.'),
  ('Düzgün onikiyüzlünün (dodekahedron) her köşesinde 3 ayrıt birleşmektedir. Bir ayrıt uzunluğu 2 cm olan düzgün onikiyüzlünün tüm ayrıtlarının toplam uzunluğu kaç cm\'dir?', '60', ['48 santimetre uzunluk', '72 santimetre uzunluk', '40 santimetre uzunluk'], 'Dodekahedronda 12 beşgen yüz vardır; E = (12·5)/2 = 30 ayrıt ve toplam uzunluk 30·2 = 60 cm olur.'),
  ('Yüksekliği 6 cm olan bir kare piramidin taban köşegeni 8√2 cm\'dir. Bu piramidin tabanına paralel bir düzlemle yüksekliğinin tepeden 1/3\'ünden kesilmesiyle elde edilen kesit karesinin alanı kaç cm²\'dir?', '64/9', ['16/3 santimetrekare', '32/9 santimetrekare', '64/3 santimetrekare'], 'Taban kenarı 8 cm, taban alanı 64 cm²; benzerlik oranı 1/3 olduğundan kesit alanı 64·(1/9) = 64/9 cm²\'dir.'),
  ('Bir dik üçgenin dik kenarları 5 cm ve 12 cm\'dir. Bu üçgenin 12 cm\'lik dik kenarı etrafında 180 derece döndürülmesiyle oluşan yarım koninin hacmi kaç π cm³\'tür?', '50', ['100 π santimetreküp', '120 π santimetreküp', '25 π santimetreküp'], 'Tam koni hacmi (1/3)π·5²·12 = 100π cm³ olduğundan 180° dönüşte yarım koni hacmi 50π cm³ olur.'),
  ('Uzayda bir düzlem içinde bulunmayan bir doğru, düzlem içindeki herhangi bir doğruya paralel ise bu doğrunun düzlemle ilişkisi nedir?', 'Düzleme paraleldir', ['Düzleme diktir', 'Düzlemi tek noktada keser', 'Düzlemle çakışıktır'], 'Düzlem dışındaki bir doğru, düzlemdeki bir doğruya paralel ise düzlemin tamamına paraleldir.'),
  ('Alt taban ayrıtı 6 cm, üst taban ayrıtı 3 cm olan eşkenar üçgen kesik dik piramidin yüksekliği 4 cm ise hacmi kaç √3 cm³\'tür?', '21', ['18√3 santimetreküp', '27√3 santimetreküp', '15√3 santimetreküp'], 'S₁ = 9√3, S₂ = 9√3/4, √(S₁S₂) = 9√3/2; V = (4/3)·(63√3/4) = 21√3 cm³ bulunur.'),
  ('Ayrıtı 6 cm olan bir küpün tüm köşelerinden geçen çevrel kürenin yüzey alanı kaç π cm²\'dir?', '108', ['36 π santimetrekare', '72 π santimetrekare', '144 π santimetrekare'], 'Çap 6√3 ise R = 3√3 cm; yüzey alanı 4πR² = 4π·27 = 108π cm² bulunur.'),
];
